function validate([skill]) {
  if (!Array.isArray(skill) || skill.length < 2 || skill.length > 100000) return 'skill has between 2 and 10^5 ratings.';
  if (skill.length % 2 !== 0) return 'skill needs an even number of players.';
  if (skill.some(v => !Number.isInteger(v) || v < 1 || v > 1000)) return 'Each rating is a whole number from 1 to 1000.';
  return null;
}

