function dividePlayers(skill) {
  skill.sort((a, b) => a - b);
  let left = 0;
  let right = skill.length - 1;
  const target = skill[left] + skill[right];
  let chemistry = 0;

  while (left < right) {
    if (skill[left] + skill[right] !== target) {
      return -1;
    }
    chemistry += skill[left] * skill[right];
    left++;
    right--;
  }
  return chemistry;
}

