function dividePlayers(skill) {
  // Try every way of pairing the players up; any equal-sum pairing gives the same chemistry.
  const used = new Array(skill.length).fill(false);
  const search = (target, sum) => {
    let first = used.indexOf(false);
    if (first === -1) return sum;
    used[first] = true;
    for (let j = first + 1; j < skill.length; j++) {
      if (used[j]) continue;
      const pair = skill[first] + skill[j];
      if (target !== null && pair !== target) continue;
      used[j] = true;
      const result = search(pair, sum + skill[first] * skill[j]);
      used[j] = false;
      if (result !== -1) { used[first] = false; return result; }
    }
    used[first] = false;
    return -1;
  };
  return search(null, 0);
}

