function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const small = size === 'small';
  const teams = small ? pick(1, 5) : 1000;
  const style = rand();
  let skill;
  if (style < 0.25) {
    // Random ratings: usually no valid split.
    const top = small ? pick(1, 6) : 1000;
    skill = Array.from({ length: 2 * teams }, () => pick(1, top));
  } else {
    // Build teams that share one combined skill, then maybe break one rating.
    const target = small ? pick(2, rand() < 0.7 ? 12 : 2000) : pick(2, 2000);
    const low = Math.max(1, target - 1000), high = Math.min(1000, target - 1);
    skill = [];
    for (let t = 0; t < teams; t++) {
      const a = pick(low, high);
      skill.push(a, target - a);
    }
    if (style > 0.8) {
      const i = pick(0, skill.length - 1);
      skill[i] = skill[i] === 1000 ? 999 : skill[i] + 1;
    }
  }
  for (let i = skill.length - 1; i > 0; i--) {
    const j = pick(0, i);
    [skill[i], skill[j]] = [skill[j], skill[i]];
  }
  return [skill];
}
